type NombreFuncion = 'duplicar' | 'incrementar' | 'cuadrado';

const funcionesDisponibles: Record<NombreFuncion, (x: number) => number> = {
  duplicar: (x) => x * 2,
  incrementar: (x) => x + 1,
  cuadrado: (x) => x * x,
};

export function compose(...fns: Array<(x: number) => number>): (x: number) => number {
  // tu código: aplica fns de derecha a izquierda
}

// probarCompose la usa el runner: compone por nombre y aplica al valor inicial.
export function probarCompose(nombres: NombreFuncion[], valorInicial: number): number {
  const fns = nombres.map((n) => funcionesDisponibles[n]);
  return compose(...fns)(valorInicial);
}
